import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { run } from './exec.js';
import * as store from '../store.js';
import * as envFile from './env.js';
import * as dbtools from './dbtools.js';
import { config } from '../config.js';
import { PROTOCOL } from './remote.js';

/**
 * A project BUNDLE — the on-the-wire format of a project move.
 *
 * Layout inside the (uncompressed) outer tar:
 *
 *   manifest.json              project + services + variables + domains + db list
 *   services/<slug>.tgz        the service folder, .git and .env included
 *   databases/<key>.dump.gz    one dump per local database found in .env
 *
 * The outer tar is NOT compressed: everything inside it already is, so a
 * second pass would only burn CPU on a multi-gigabyte stream.
 */

export { PROTOCOL };

// Reinstallable by the build step — skipped unless "dependencies" is ticked.
const DEPENDENCY_DIRS = [
  'node_modules', 'vendor', 'bower_components', '.pnpm-store', '.yarn/cache',
  '.venv', 'venv', 'env/lib', 'Pods', 'target', '.bundle',
];
// Regenerated by the build step — skipped unless "build caches" is ticked.
// Note: dist / build / out are NOT here; a static site must keep working the
// moment it lands, even before its first rebuild.
const CACHE_DIRS = [
  '.next', '.nuxt', '.svelte-kit', '.angular', '.cache', '.turbo', '.parcel-cache',
  '.vite', '__pycache__', '.pytest_cache', '.mypy_cache', '.ruff_cache', '.gradle',
  '.terraform', 'coverage', '.nyc_output', '.eslintcache',
];

/** Sizes a human reads at a glance: 812 KB, 4.3 MB, 1.21 GB. */
export function formatSize(bytes) {
  const n = Number(bytes) || 0;
  if (n < 1024) return `${n} B`;
  if (n < 1048576) return `${Math.round(n / 1024)} KB`;
  if (n < 1073741824) return `${(n / 1048576).toFixed(n < 10485760 ? 1 : 0)} MB`;
  return `${(n / 1073741824).toFixed(2)} GB`;
}

export function excludesFor(options = {}) {
  const out = [];
  if (!options.dependencies) out.push(...DEPENDENCY_DIRS);
  if (!options.caches) out.push(...CACHE_DIRS);
  return out;
}

export const DEFAULT_OPTIONS = {
  dependencies: false, // node_modules & friends — the deploy reinstalls them
  caches: false, // build caches — the deploy rebuilds them
  databases: true, // local MySQL / PostgreSQL / MongoDB found in .env
  domains: true, // recreate nginx vhosts (+ HTTPS) on the target
  history: true, // deployment history
  deploy: true, // run a deploy on arrival so the project comes up by itself
  stopSource: true, // stop the source processes while copying (clean snapshot)
  removeSource: true, // a MOVE: delete the project here once the target is up
};

export function normalizeOptions(input = {}) {
  const out = { ...DEFAULT_OPTIONS };
  for (const k of Object.keys(DEFAULT_OPTIONS)) {
    if (k in input) out[k] = Boolean(input[k]);
  }
  if (typeof input.rename === 'string' && input.rename.trim()) out.rename = input.rename.trim();
  return out;
}

/** First non-internal IPv4 — shown in the "repoint your DNS" hint. */
function primaryAddress() {
  for (const addrs of Object.values(os.networkInterfaces())) {
    for (const a of addrs || []) if (a.family === 'IPv4' && !a.internal) return a.address;
  }
  return '';
}

/** This panel's identity, as the other side sees it. */
export function localInfo() {
  return {
    protocol: PROTOCOL,
    hostname: os.hostname(),
    address: primaryAddress(),
    panel: '0.1.0',
    node: process.version,
    projectsRoot: config.projectsRoot,
    tools: dbtools.toolReport(),
  };
}

/* ------------------------------------------------------------------ sizes */

async function dirBytes(dir, excludes = []) {
  if (!dir || !fs.existsSync(dir)) return 0;
  const r = await run('du', ['-sb', ...excludes.map((e) => `--exclude=${e}`), dir], { timeout: 180_000 });
  const n = Number(String(r.stdout || '').trim().split(/\s+/)[0]);
  return Number.isFinite(n) ? n : 0;
}

export async function freeBytes(dir) {
  const target = fs.existsSync(dir) ? dir : path.dirname(dir);
  const r = await run('df', ['-B1', '--output=avail', target], { timeout: 20000 });
  const n = Number(String(r.stdout || '').trim().split('\n').pop());
  return Number.isFinite(n) ? n : 0;
}

/* ------------------------------------------------------------------- plan */

/** Unique, filesystem-safe key per service inside a bundle. */
function slugsFor(services) {
  const used = new Set();
  const map = new Map();
  for (const s of services) {
    let slug = store.slugify(s.name);
    let n = 2;
    while (used.has(slug)) slug = `${store.slugify(s.name)}-${n++}`;
    used.add(slug);
    map.set(s.id, slug);
  }
  return map;
}

/** The panel must never bundle (or delete) the folder it runs from. */
function guardPath(target) {
  const real = path.resolve(target || '');
  const panel = path.resolve(config.rootDir);
  if (!real) return null;
  if (real === panel || panel.startsWith(`${real}/`) || real === path.resolve(config.projectsRoot) || real === '/') {
    return `${real} holds the panel itself — refusing to include it`;
  }
  return null;
}

/**
 * Everything the other side needs to decide whether it can take this
 * project: sizes with the chosen excludes applied, ports, pm2 names,
 * domains and the databases found in each .env. No secrets — credentials
 * travel inside the bundle, not in the plan.
 */
export async function buildPlan(projectId, optionsInput = {}) {
  const options = normalizeOptions(optionsInput);
  const project = store.getProject(projectId);
  if (!project) throw new Error('Project not found');
  const services = project.services || [];
  const slugs = slugsFor(services);
  const excludes = excludesFor(options);
  const projectRoot = store.projectPath(project);
  // warnings = something is off and may need fixing;
  // notes = expected follow-up work that no panel can do for you.
  const warnings = [];
  const notes = [];

  const plan = {
    protocol: PROTOCOL,
    source: localInfo(),
    options,
    project: {
      id: project.id,
      name: project.name,
      slug: store.slugify(project.name),
      description: project.description || '',
      path: projectRoot,
      createdAt: project.createdAt,
      pinned: Boolean(project.pinned),
    },
    services: [],
    databases: [],
    warnings,
    notes,
  };

  for (const svc of services) {
    const slug = slugs.get(svc.id);
    const guard = guardPath(svc.localPath);
    if (guard) warnings.push(`${svc.name}: ${guard}`);

    const rel = svc.localPath ? path.relative(projectRoot, svc.localPath) : '';
    const inside = Boolean(rel) && !rel.startsWith('..') && !path.isAbsolute(rel);
    if (svc.localPath && !inside) {
      warnings.push(`${svc.name}: lives outside the project folder (${svc.localPath}) — it will land in the target's project folder as "${slug}"`);
    }

    const exists = Boolean(svc.localPath) && fs.existsSync(svc.localPath);
    if (!exists) warnings.push(`${svc.name}: no folder on disk yet (${svc.localPath || 'no path set'}) — only its settings move`);

    const vars = envFile.readServiceVariables(svc).variables || {};
    const dbs = options.databases ? dbtools.detectDatabases(vars) : [];
    const caches = dbtools.detectCaches(vars);

    plan.services.push({
      slug,
      name: svc.name,
      kind: svc.serviceKind || 'auto',
      sourceType: svc.sourceType,
      repoFullName: svc.repoFullName || '',
      branch: svc.branch || '',
      pm2Name: svc.pm2Name || svc.name,
      pm2NamePinned: Boolean(svc.pm2NamePinned),
      port: svc.port || '',
      localPath: svc.localPath || '',
      relPath: inside ? rel : slug,
      exists,
      skip: Boolean(guard),
      bytes: guard ? 0 : await dirBytes(svc.localPath, excludes),
      variableCount: Object.keys(vars).length,
      autoDeploy: Boolean(svc.autoDeploy),
      domains: (svc.domains || []).map((d) => ({ host: d.host, https: Boolean(d.https), port: d.port || null, root: d.root || null })),
      databases: dbs.map((d) => ({ kind: d.kind, name: d.name, host: d.host, local: d.local, source: d.source, key: d.key })),
      caches,
    });

    for (const d of dbs) {
      plan.databases.push({ serviceSlug: slug, kind: d.kind, name: d.name, host: d.host, local: d.local, source: d.source, key: d.key });
      if (!d.local) {
        notes.push(`${svc.name}: ${d.kind} "${d.name}" lives on ${d.host} — left where it is, the moved app keeps using it`);
      }
    }
    if (caches.length && options.databases) {
      notes.push(`${svc.name}: ${caches.join(', ')} points at a cache store — caches are never copied, they refill themselves`);
    }
  }

  plan.totals = {
    services: plan.services.length,
    bytes: plan.services.reduce((n, s) => n + s.bytes, 0),
    domains: plan.services.reduce((n, s) => n + s.domains.length, 0),
    databases: plan.databases.filter((d) => d.local).length,
    autoDeploy: plan.services.filter((s) => s.autoDeploy).length,
  };
  return plan;
}

/* ------------------------------------------------------------------ build */

const KEEP_FULL_LOGS = 10; // newest deployments keep their log; older ones metadata only
const KEEP_DEPLOYMENTS = 50;

/**
 * Stage a bundle in `dir`. Returns the manifest (also written to disk).
 * `log` receives human-readable progress lines.
 */
export async function buildBundle({ projectId, options: optionsInput, dir, log = () => {} }) {
  const options = normalizeOptions(optionsInput);
  const plan = await buildPlan(projectId, options);
  const project = store.getProject(projectId);
  const services = project.services || [];
  const slugs = slugsFor(services);
  const excludes = excludesFor(options);

  fs.mkdirSync(path.join(dir, 'services'), { recursive: true });
  fs.mkdirSync(path.join(dir, 'databases'), { recursive: true });

  const manifest = {
    protocol: PROTOCOL,
    createdAt: new Date().toISOString(),
    source: localInfo(),
    options,
    project: {
      name: project.name,
      description: project.description || '',
      createdAt: project.createdAt,
      createdAtHistory: project.createdAtHistory || [],
      pinned: Boolean(project.pinned),
    },
    services: [],
    databases: [],
    warnings: [...plan.warnings],
    notes: [...plan.notes],
  };

  if (excludes.length) log(`Skipping ${excludes.slice(0, 6).join(', ')}${excludes.length > 6 ? `, +${excludes.length - 6} more` : ''} (rebuilt on arrival)`);

  for (const svc of services) {
    const slug = slugs.get(svc.id);
    const planned = plan.services.find((s) => s.slug === slug);
    const vars = envFile.readServiceVariables(svc).variables || {};
    const entry = {
      slug,
      name: svc.name,
      icon: svc.icon || 'box',
      sourceType: svc.sourceType,
      repoUrl: svc.repoUrl || '',
      repoFullName: svc.repoFullName || '',
      branch: svc.branch || 'main',
      rootDirectory: svc.rootDirectory || '',
      relPath: planned?.relPath || slug,
      originalPath: svc.localPath || '',
      serviceKind: svc.serviceKind || 'auto',
      buildCommand: svc.buildCommand || '',
      startCommand: svc.startCommand || '',
      staticOutputDir: svc.staticOutputDir || '',
      pm2Name: svc.pm2Name || '',
      pm2NamePinned: Boolean(svc.pm2NamePinned),
      port: svc.port || '',
      autoDeploy: Boolean(svc.autoDeploy),
      domains: svc.domains || [],
      variables: vars,
      createdAt: svc.createdAt,
      createdAtHistory: svc.createdAtHistory || [],
      archive: null,
      bytes: 0, // size on the wire (the compressed archive)
      sourceBytes: planned?.bytes || 0, // size once unpacked again
    };

    if (planned?.skip) {
      log(`! ${svc.name}: skipped — ${plan.warnings.find((w) => w.startsWith(`${svc.name}:`)) || 'protected path'}`);
    } else if (planned?.exists) {
      const archive = path.join('services', `${slug}.tgz`);
      const out = path.join(dir, archive);
      log(`Packing ${svc.name} (${svc.localPath})…`);
      const args = [
        '-czf', out, '--numeric-owner', '--ignore-failed-read',
        '--warning=no-file-changed', '--warning=no-file-ignored', '--warning=no-file-removed',
        ...excludes.map((e) => `--exclude=${e}`),
        '-C', svc.localPath, '.',
      ];
      const r = await run('tar', args, { timeout: 3 * 3600_000 });
      // tar exits 1 for "file changed/vanished while reading" — the archive
      // is still valid, so only a hard failure (2) aborts the bundle.
      if (r.code !== 0 && r.code !== 1) {
        throw new Error(`tar failed for ${svc.name}: ${String(r.stderr || r.stdout).trim().split('\n').slice(-3).join(' · ')}`);
      }
      if (r.code === 1) log(`  (tar note: ${String(r.stderr).trim().split('\n').slice(-1)[0]})`, 'warn');
      entry.archive = archive;
      entry.bytes = fs.statSync(out).size;
      log(`  ${svc.name}: ${formatSize(entry.bytes)} packed`);
    }

    if (options.history) {
      const deployments = store.listDeployments(svc.id).slice(0, KEEP_DEPLOYMENTS);
      entry.deployments = deployments.map((d, i) => {
        const { id, serviceId, ...rest } = d;
        return {
          ...rest,
          serviceSlug: slug,
          logs: i < KEEP_FULL_LOGS ? d.logs || [] : [],
        };
      });
      if (deployments.length) log(`  ${svc.name}: ${deployments.length} deployment(s) of history`);
    }

    // Databases: dump the local ones, note the remote ones.
    if (options.databases) {
      for (const db of dbtools.detectDatabases(vars)) {
        if (!db.local) continue;
        const file = path.join('databases', `${slug}-${db.kind}-${db.name}`.replace(/[^\w.-]/g, '_') + '.dump');
        log(`Dumping ${dbtools.describeDb(db)}…`);
        const res = await dbtools.dumpDatabase(db, path.join(dir, file), dir);
        if (!res.ok) {
          throw new Error(
            `could not dump ${dbtools.describeDb(db)}: ${res.output || 'unknown error'}. ` +
              `Fix the credentials in ${svc.name}'s .env, or untick Databases and move that database yourself.`
          );
        }
        const bytes = fs.existsSync(path.join(dir, file)) ? fs.statSync(path.join(dir, file)).size : 0;
        manifest.databases.push({
          serviceSlug: slug, kind: db.kind, name: db.name, user: db.user, password: db.password,
          host: db.host, port: db.port, uri: db.uri || '', source: db.source, file, bytes,
        });
        log(`  ${db.name}: ${formatSize(bytes)} dumped`);
      }
    }

    manifest.services.push(entry);
  }

  fs.writeFileSync(path.join(dir, 'manifest.json'), JSON.stringify(manifest, null, 2));
  return manifest;
}

/** Wrap a staged bundle directory into one streamable tar file. */
export async function packBundle(dir, outFile) {
  const r = await run('tar', ['-cf', outFile, '--numeric-owner', '-C', dir, '.'], { timeout: 3 * 3600_000 });
  if (r.code !== 0) throw new Error(`packing the bundle failed: ${String(r.stderr || r.stdout).trim().slice(-300)}`);
  return fs.statSync(outFile).size;
}

export async function unpackBundle(file, destDir) {
  fs.mkdirSync(destDir, { recursive: true });
  const r = await run('tar', ['-xf', file, '--numeric-owner', '-C', destDir], { timeout: 3 * 3600_000 });
  if (r.code !== 0) throw new Error(`unpacking the bundle failed: ${String(r.stderr || r.stdout).trim().slice(-300)}`);
  const manifestFile = path.join(destDir, 'manifest.json');
  if (!fs.existsSync(manifestFile)) throw new Error('the uploaded file is not a project bundle (no manifest.json inside)');
  const manifest = JSON.parse(fs.readFileSync(manifestFile, 'utf8'));
  if (Number(manifest.protocol) !== PROTOCOL) {
    throw new Error(`bundle protocol v${manifest.protocol} cannot be read by this panel (v${PROTOCOL}) — update both sides`);
  }
  return manifest;
}

/** Extract one service archive into its target folder. */
export async function extractService(bundleDir, entry, targetPath) {
  fs.mkdirSync(targetPath, { recursive: true });
  const archive = path.join(bundleDir, entry.archive);
  const r = await run('tar', ['-xf', archive, '--numeric-owner', '-C', targetPath], { timeout: 3 * 3600_000 });
  if (r.code !== 0 && r.code !== 1) {
    throw new Error(`restoring ${entry.name} failed: ${String(r.stderr || r.stdout).trim().slice(-300)}`);
  }
  return true;
}

/** Plan a bundle without a store project (used on the receiving side). */
export function planFromManifest(manifest) {
  return {
    protocol: manifest.protocol,
    source: manifest.source,
    options: manifest.options,
    project: { name: manifest.project.name, slug: store.slugify(manifest.project.name) },
    services: (manifest.services || []).map((s) => ({
      slug: s.slug,
      name: s.name,
      kind: s.serviceKind,
      sourceType: s.sourceType,
      autoDeploy: s.autoDeploy,
      pm2Name: s.pm2Name,
      pm2NamePinned: s.pm2NamePinned,
      port: s.port,
      relPath: s.relPath,
      bytes: s.bytes,
      domains: s.domains || [],
      databases: (manifest.databases || []).filter((d) => d.serviceSlug === s.slug).map((d) => ({ kind: d.kind, name: d.name, host: d.host, local: true })),
    })),
    databases: (manifest.databases || []).map((d) => ({ serviceSlug: d.serviceSlug, kind: d.kind, name: d.name, host: d.host, local: true })),
    totals: {
      services: (manifest.services || []).length,
      bytes: (manifest.services || []).reduce((n, s) => n + (s.sourceBytes || s.bytes || 0), 0),
      wireBytes: (manifest.services || []).reduce((n, s) => n + (s.bytes || 0), 0),
      domains: (manifest.services || []).reduce((n, s) => n + (s.domains || []).length, 0),
      databases: (manifest.databases || []).length,
    },
    warnings: manifest.warnings || [],
    notes: manifest.notes || [],
  };
}
